package patterns2;

public class pattern12 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
     int rows=5,cols=5;
     for(int r=1;r<=rows;r++)
     {
    	 for(int c=cols;c>=1;c--)
    	 {
    		 System.out.print(c+" ");
    	 }
    	 System.out.println();
     }
	}
}
